insert into public.form_templates (id,code,title,purpose,document_id,schema,status,rev) values
('c53cd710-4198-57ce-8acc-494183ebd165'::uuid,'STEP-RECORD','Step record','One-tap record that a step was carried out, with any change from the written step.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "outcome", "label": "Outcome", "type": "select", "required": true, "options": ["Done as written", "Done with changes"]}, {"key": "remarks", "label": "Remarks or changes", "type": "textarea", "required": false, "hint": "What was done differently, and why. No names of affected persons."}, {"key": "evidence_ref", "label": "Record or file reference", "type": "text", "required": false, "hint": "Logbook entry, memo, photo or Vault reference"}]}'::jsonb,'draft',1),
('a1cea359-7cc0-591b-81f9-6dbe26d0ce13'::uuid,'HR-F04','Duty handover checklist','Annex 2-E: what the outgoing duty team hands over.','f379ea8e-ae82-5eb6-9887-f700227215ce'::uuid,'{"fields": [{"key": "shift", "label": "Shift", "type": "select", "required": true, "options": ["06:00-14:00", "14:00-22:00", "22:00-06:00", "Other"]}, {"key": "streams", "label": "Monitoring streams covered", "type": "multiselect", "required": true, "options": ["City Traffic Monitoring", "Public Safety", "Emergency Monitoring"]}, {"key": "active_warnings", "label": "Warnings and bulletins in force", "type": "textarea", "required": true}, {"key": "open_incidents", "label": "Open incidents", "type": "integer", "required": true, "min": 0}, {"key": "pending_requests", "label": "Pending resource requests", "type": "integer", "required": true, "min": 0}, {"key": "radio_check", "label": "Radio net check", "type": "select", "required": true, "options": ["All stations answered", "Some stations did not answer", "Not done"]}, {"key": "missing_stations", "label": "Stations that did not answer", "type": "textarea", "required": false}, {"key": "equipment", "label": "Generator, UPS and backup internet", "type": "select", "required": true, "options": ["All working", "Issue noted"]}, {"key": "equipment_issue", "label": "Equipment issue", "type": "textarea", "required": false}, {"key": "incoming_ack", "label": "Incoming duty officer has read and accepted the handover", "type": "checkbox", "required": true}]}'::jsonb,'draft',1),
('fd56b92d-dd27-5167-b14f-b8d2e3519f55'::uuid,'EOC-WARN-01','Bulletin and advisory log','Each hazard bulletin received, as the first step of warning dissemination.','69e884bf-8590-5061-99a1-38fb8c0769a4'::uuid,'{"fields": [{"key": "issuer", "label": "Issuer", "type": "select", "required": true, "options": ["PAGASA", "PHIVOLCS", "MGB", "NDRRMC / OCD", "Other"]}, {"key": "bulletin_no", "label": "Bulletin or advisory number", "type": "text", "required": true}, {"key": "issued_at", "label": "Time issued", "type": "datetime", "required": true}, {"key": "hazard", "label": "Hazard", "type": "select", "required": true, "options": ["Tropical cyclone", "Storm surge", "Riverine flood", "Flash flood", "Rain-induced landslide", "Drought (El Nino)", "Extreme heat", "Earthquake", "Tsunami", "Industrial / geothermal incident", "Disease outbreak", "Other"]}, {"key": "areas", "label": "Areas affected", "type": "textarea", "required": true}]}'::jsonb,'draft',1),
('ab5f1657-b7bd-5b05-a65e-5c14dcd5251c'::uuid,'EOC-WARN-02','Warning receipt confirmation','Barangays notified and confirmed, by channel.','69e884bf-8590-5061-99a1-38fb8c0769a4'::uuid,'{"fields": [{"key": "barangays_notified", "label": "Barangays notified", "type": "integer", "required": true, "min": 0}, {"key": "barangays_confirmed", "label": "Barangays that confirmed receipt", "type": "integer", "required": true, "min": 0}, {"key": "channels", "label": "Channels used", "type": "multiselect", "required": true, "options": ["Cell broadcast / SMS", "Radio", "Social media", "Barangay officials", "Public address"]}, {"key": "unconfirmed", "label": "Barangays still to confirm", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('975ce83f-c327-567d-934f-87d1db78066a'::uuid,'EOC-ACT-01','EOC activation record','Level, authority and contingency plan for an activation.','69e884bf-8590-5061-99a1-38fb8c0769a4'::uuid,'{"fields": [{"key": "level", "label": "Level", "type": "select", "required": true, "options": ["Blue", "Red"]}, {"key": "authority_ref", "label": "Authority (memo or instruction)", "type": "text", "required": true}, {"key": "plan_code", "label": "Contingency plan activated", "type": "text", "required": false, "hint": "For example CP-FLOOD-LUNOP"}, {"key": "reason", "label": "Reason", "type": "textarea", "required": true}]}'::jsonb,'draft',1),
('e675ecec-bcf9-5d65-b338-eaa230d8595f'::uuid,'EOC-GIS-06','Evacuation centre and route status','EOC Module form EOC-GIS-06: centres open, capacity and access.','c4693fb2-e773-5bae-ad3a-be15c30b6131'::uuid,'{"fields": [{"key": "centres_open", "label": "Evacuation centres open", "type": "integer", "required": true, "min": 0}, {"key": "capacity_persons", "label": "Total capacity (persons)", "type": "integer", "required": false, "min": 0}, {"key": "occupancy_persons", "label": "Current occupancy (persons)", "type": "integer", "required": false, "min": 0}, {"key": "route_issues", "label": "Access routes blocked or limited", "type": "textarea", "required": false}, {"key": "location_status", "label": "Reliability of this information", "type": "select", "required": true, "options": ["Reported", "Preliminary", "Field-verified", "Official"]}]}'::jsonb,'draft',1),
('74d04cd9-7639-5f46-b1d1-76e1fec12dbe'::uuid,'EOC-SITREP-01','SitRep submission record','DILG VIII cut-offs: which SitRep went where and when.','c4693fb2-e773-5bae-ad3a-be15c30b6131'::uuid,'{"fields": [{"key": "sitrep_no", "label": "SitRep number", "type": "text", "required": true}, {"key": "period_end", "label": "End of reporting period", "type": "datetime", "required": true}, {"key": "barangays_reporting", "label": "Barangays reporting", "type": "integer", "required": true, "min": 0}, {"key": "sent_at", "label": "Time sent to OCD VIII and the Province", "type": "datetime", "required": true}, {"key": "cut_off_met", "label": "Sent before the cut-off", "type": "checkbox", "required": false}]}'::jsonb,'draft',1),
('11a50607-7be4-5099-a6dd-e5d9b4338327'::uuid,'GOV-F09','PDRA summary','Annex 1-G GOV-F09: the PDRA decision and its basis.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "hazard", "label": "Hazard", "type": "select", "required": true, "options": ["Tropical cyclone", "Storm surge", "Riverine flood", "Flash flood", "Rain-induced landslide", "Drought (El Nino)", "Extreme heat", "Earthquake", "Tsunami", "Industrial / geothermal incident", "Disease outbreak", "Other"]}, {"key": "forecast_source", "label": "Forecast source and number", "type": "text", "required": true}, {"key": "expected_impact_at", "label": "Expected impact", "type": "datetime", "required": true}, {"key": "lead_time_hours", "label": "Lead time left (hours)", "type": "number", "required": true, "min": 0}, {"key": "impact_class", "label": "Projected impact", "type": "select", "required": true, "options": ["Minor", "Moderate", "Severe"]}, {"key": "decision", "label": "Decision", "type": "select", "required": true, "options": ["Monitor", "City early action", "Request a State of Imminent Disaster"]}, {"key": "basis", "label": "Basis of the decision", "type": "textarea", "required": true}]}'::jsonb,'draft',1),
('e1a1b99f-bce4-525c-9ebe-680a3b7d8ebf'::uuid,'GOV-F10','Request to RDRRMC VIII','Annex 1-G GOV-F10: the City request and its acknowledgment.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "cdrrmc_resolution", "label": "CDRRMC resolution endorsing the request", "type": "text", "required": true}, {"key": "sent_at", "label": "Time sent", "type": "datetime", "required": true}, {"key": "channel", "label": "Channel", "type": "select", "required": true, "options": ["Email", "Courier", "Hand-carried", "Other"]}, {"key": "acknowledgment_ref", "label": "Acknowledgment reference", "type": "text", "required": false}]}'::jsonb,'draft',1),
('b1cdbb53-37e1-501e-88e9-331c531a8be0'::uuid,'GOV-F11','Mayor''s Executive Order record','Annex 1-G GOV-F11: the declaration as issued.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "eo_number", "label": "Executive Order number", "type": "text", "required": true}, {"key": "declared_at", "label": "Time of declaration", "type": "datetime", "required": true}, {"key": "areas", "label": "Areas covered", "type": "textarea", "required": true}, {"key": "validity", "label": "Validity", "type": "text", "required": true}]}'::jsonb,'draft',1),
('7ce40839-7edd-5950-9ee2-783369770b83'::uuid,'GOV-F07','State of Calamity technical assessment','Annex 1-G GOV-F07: RDANA-based assessment for the CDRRMC.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "rdana_ref", "label": "RDANA report reference", "type": "text", "required": true}, {"key": "affected_barangays", "label": "Affected barangays", "type": "integer", "required": true, "min": 0}, {"key": "affected_families", "label": "Affected families", "type": "integer", "required": false, "min": 0}, {"key": "displaced_persons", "label": "Displaced persons", "type": "integer", "required": false, "min": 0}, {"key": "damage_estimate_php", "label": "Estimated damage (PHP)", "type": "number", "required": false, "min": 0}, {"key": "criteria_basis", "label": "Criteria met and basis", "type": "textarea", "required": true}]}'::jsonb,'draft',1),
('0fa30987-c47b-5b02-a23f-1eac965e42b6'::uuid,'GOV-F08','State of Calamity recommendation and resolution','Annex 1-G GOV-F08, with the declaration every QRF resolution must cite (A1.6).','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "cdrrmc_resolution", "label": "CDRRMC recommendation (resolution number)", "type": "text", "required": true}, {"key": "sp_resolution", "label": "Sangguniang Panlungsod resolution number", "type": "text", "required": true}, {"key": "declared_on", "label": "Date declared", "type": "date", "required": true}, {"key": "qrf_declaration_ref", "label": "Declaration cited for QRF use", "type": "text", "required": true, "hint": "SP resolution or Proclamation number and date"}]}'::jsonb,'draft',1),
('243e7dba-cefb-5b4d-8e17-4f35006c1a03'::uuid,'GOV-F12','Lifting record','Annex 1-G GOV-F12: ground and basis for lifting.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "lifting_ground", "label": "Ground", "type": "select", "required": true, "options": ["Hazard occurred", "Projected impacts not met"]}, {"key": "basis", "label": "Basis (advisory, incident report or latest PDRA)", "type": "textarea", "required": true}, {"key": "lifted_at", "label": "Time lifted", "type": "datetime", "required": true}]}'::jsonb,'draft',1),
('09b7514a-5043-5252-a6c3-3cf92324df2d'::uuid,'GOV-F13','Post-lifting 45-day report','Annex 1-G GOV-F13: report to OCD within 45 days.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "report_ref", "label": "Report reference", "type": "text", "required": true}, {"key": "submitted_on", "label": "Date submitted", "type": "date", "required": true}, {"key": "aa_funds_used_php", "label": "Anticipatory action funds used (PHP)", "type": "number", "required": false, "min": 0}, {"key": "costs_minimized", "label": "Estimated costs minimized", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('6746ed1c-8b67-5310-aa8a-31a84a27d7f6'::uuid,'EOC-FF-01','Flash flood early action record','Reading, threshold and actions for a short-lead hazard.','69e884bf-8590-5061-99a1-38fb8c0769a4'::uuid,'{"fields": [{"key": "source", "label": "Gauge or source", "type": "text", "required": true}, {"key": "reading", "label": "Reading and threshold reached", "type": "text", "required": true}, {"key": "barangays_alerted", "label": "Barangays alerted", "type": "integer", "required": true, "min": 0}, {"key": "families_moved", "label": "Families moved pre-emptively", "type": "integer", "required": false, "min": 0}]}'::jsonb,'draft',1),
('3f9a6288-8f27-59e7-86f7-63ae2ad33a37'::uuid,'GOV-F03','CDRRMC attendance and minutes','Annex 1-G GOV-F03: quorum, presiding officer and decisions.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "meeting_date", "label": "Meeting date", "type": "date", "required": true}, {"key": "meeting_type", "label": "Meeting", "type": "select", "required": true, "options": ["Regular (quarterly)", "Special"]}, {"key": "members_present", "label": "Members present", "type": "integer", "required": true, "min": 0}, {"key": "quorum_met", "label": "Quorum met", "type": "checkbox", "required": true}, {"key": "presiding_designation", "label": "Written designation of the presiding officer (if not the Chair)", "type": "text", "required": false}, {"key": "resolutions", "label": "Resolutions adopted (numbers)", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('4abad9a2-4347-58f3-bc20-d34862057d66'::uuid,'BUD-F01','LDRRMF thematic split','MOO Ch.1 sec. 1.4 and Ch.2 sec. 2.16.2: how the investment plan splits across thematic areas.','f379ea8e-ae82-5eb6-9887-f700227215ce'::uuid,'{"fields": [{"key": "fiscal_year", "label": "Fiscal year", "type": "integer", "required": true, "min": 2020}, {"key": "total_php", "label": "Total LDRRMF (PHP)", "type": "number", "required": true, "min": 0}, {"key": "prevention_pct", "label": "Prevention and mitigation (% of the 70%)", "type": "number", "required": true, "min": 0}, {"key": "preparedness_pct", "label": "Preparedness (% of the 70%)", "type": "number", "required": true, "min": 0}, {"key": "response_pct", "label": "Response (% of the 70%)", "type": "number", "required": true, "min": 0}, {"key": "recovery_pct", "label": "Recovery and rehabilitation (% of the 70%)", "type": "number", "required": true, "min": 0}, {"key": "aa_line_php", "label": "Anticipatory action line (PHP)", "type": "number", "required": false, "min": 0}, {"key": "tagged", "label": "Every line tagged to an LDRRMP/CDP PPA", "type": "checkbox", "required": true}]}'::jsonb,'draft',1),
('97e4f411-ff60-5aa6-9afa-ce27a305039b'::uuid,'BUD-F02','Quarterly results-and-finance report','Ch.2 sec. 2.16.2 step 7: one report that every division feeds.','f379ea8e-ae82-5eb6-9887-f700227215ce'::uuid,'{"fields": [{"key": "quarter", "label": "Quarter", "type": "select", "required": true, "options": ["Q1", "Q2", "Q3", "Q4"]}, {"key": "obligation_rate_pct", "label": "Obligation rate (%)", "type": "number", "required": true, "min": 0}, {"key": "results", "label": "Results against the LDRRMP", "type": "textarea", "required": true}, {"key": "issues", "label": "Issues and proposed realignments", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('cca25880-3d5b-58e2-9d1d-d587bb188f57'::uuid,'CL-F01','Contingency plan activation','MOO Ch.1 sec. 6.3: plan, level and authority for cluster activation.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "plan_code", "label": "Contingency plan", "type": "select", "required": true, "options": ["CP-FLOOD-LUNOP", "CP-EARTHQUAKE", "CP-FLASHFLOOD", "CP-LANDSLIDE", "CP-DROUGHT", "CP-DISEASE", "CP-INDUSTRIAL"]}, {"key": "level", "label": "EOC level", "type": "select", "required": true, "options": ["Blue", "Red"]}, {"key": "authority_ref", "label": "Authority (memo or instruction)", "type": "text", "required": true}]}'::jsonb,'draft',1),
('547648f5-c5d8-582f-88de-adf46d542e23'::uuid,'CL-F02','Cluster roll-call','Clusters notified and focal persons confirmed.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "notified", "label": "Clusters notified", "type": "multiselect", "required": true, "options": ["Food and Non-Food Items", "Camp Coordination and Camp Management", "Protection", "Health (WASH, nutrition, MHPSS)", "Logistics", "Emergency Telecommunications", "Education", "Search, Rescue and Retrieval", "Law and Order", "Management of the Dead and Missing"]}, {"key": "confirmed", "label": "Clusters that confirmed a focal person", "type": "multiselect", "required": true, "options": ["Food and Non-Food Items", "Camp Coordination and Camp Management", "Protection", "Health (WASH, nutrition, MHPSS)", "Logistics", "Emergency Telecommunications", "Education", "Search, Rescue and Retrieval", "Law and Order", "Management of the Dead and Missing"]}, {"key": "unreachable", "label": "Clusters not yet reached, and follow-up", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('0a5f38b0-ed38-585e-9051-07a88176c5cf'::uuid,'CL-F03','Cluster coordination meeting','Needs, gaps and requests from the clusters.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "meeting_at", "label": "Meeting time", "type": "datetime", "required": true}, {"key": "priority_needs", "label": "Priority needs", "type": "textarea", "required": true}, {"key": "gaps", "label": "Gaps and constraints", "type": "textarea", "required": false}, {"key": "requests_raised", "label": "Resource requests raised", "type": "integer", "required": false, "min": 0}]}'::jsonb,'draft',1),
('fe3f7eff-1901-5994-872b-78fde7e4c2b8'::uuid,'CL-F04','Cluster stand-down','Clusters stood down and why.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'{"fields": [{"key": "stood_down", "label": "Clusters stood down", "type": "multiselect", "required": true, "options": ["Food and Non-Food Items", "Camp Coordination and Camp Management", "Protection", "Health (WASH, nutrition, MHPSS)", "Logistics", "Emergency Telecommunications", "Education", "Search, Rescue and Retrieval", "Law and Order", "Management of the Dead and Missing"]}, {"key": "reason", "label": "Reason", "type": "textarea", "required": true}]}'::jsonb,'draft',1),
('44b0278a-37f4-5121-8702-6cd49531a367'::uuid,'HR-F05','EOC designation review','Annex 2-D: quarterly check that key EOC positions are covered two deep.','f379ea8e-ae82-5eb6-9887-f700227215ce'::uuid,'{"fields": [{"key": "positions_total", "label": "Key positions", "type": "integer", "required": true, "min": 0}, {"key": "positions_two_deep", "label": "Positions covered two deep", "type": "integer", "required": true, "min": 0}, {"key": "gaps", "label": "Positions to fill, and offices asked", "type": "textarea", "required": true}]}'::jsonb,'draft',1),
('2dc74822-eb92-5dd3-a1f8-7888fcfb3299'::uuid,'HR-F06','Designee briefing record','Orientation of newly approved designees.','f379ea8e-ae82-5eb6-9887-f700227215ce'::uuid,'{"fields": [{"key": "briefing_date", "label": "Briefing date", "type": "date", "required": true}, {"key": "designees_briefed", "label": "Designees briefed", "type": "integer", "required": true, "min": 0}, {"key": "topics", "label": "Topics covered", "type": "multiselect", "required": true, "options": ["Activation and call-out", "Position checklist", "Communications", "Safety and welfare", "Records"]}]}'::jsonb,'draft',1),
('ce695929-81c2-5645-a3f1-e86bfbaf6711'::uuid,'EOC-GIS-REF','EOC geospatial reference check','SOP 6-GIS-01 step 1: confirm the reference point on the ground.','c4693fb2-e773-5bae-ad3a-be15c30b6131'::uuid,'{"fields": [{"key": "point_code", "label": "Reference point", "type": "text", "required": true, "hint": "For example EOC or EOC-ALT"}, {"key": "result", "label": "Result", "type": "select", "required": true, "options": ["Matches the facility entrance", "Needs correction", "Not yet surveyed"]}, {"key": "survey_date", "label": "Survey date", "type": "date", "required": false}, {"key": "method", "label": "Method", "type": "text", "required": false, "hint": "Handheld GPS, survey-grade GNSS, orthophoto"}]}'::jsonb,'draft',1),
('214f2bf6-7917-5896-bb02-409897118e71'::uuid,'EOC-GIS-01','Geospatial data inventory','EOC-GIS-01: map layers, custodians, sources and update status.','c4693fb2-e773-5bae-ad3a-be15c30b6131'::uuid,'{"fields": [{"key": "layers_listed", "label": "Layers listed", "type": "integer", "required": true, "min": 0}, {"key": "custodians_confirmed", "label": "Custodian confirmed for every layer", "type": "checkbox", "required": true}, {"key": "missing", "label": "Layers still missing", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('dc057253-9c58-5d48-a848-4e7fcec54729'::uuid,'EOC-GIS-02','Geospatial data validation sheet','EOC-GIS-02: coordinate system, date, completeness and validation.','c4693fb2-e773-5bae-ad3a-be15c30b6131'::uuid,'{"fields": [{"key": "layer_code", "label": "Layer", "type": "text", "required": true}, {"key": "crs", "label": "Coordinate reference system", "type": "text", "required": true, "hint": "EPSG:4326 for longitude/latitude"}, {"key": "issued_on", "label": "Date of issue or collection", "type": "date", "required": false}, {"key": "completeness", "label": "Completeness", "type": "select", "required": true, "options": ["Complete", "Partial", "Unknown"]}, {"key": "validation_status", "label": "Validation status", "type": "select", "required": true, "options": ["Reported", "Preliminary", "Field-verified", "Official"]}, {"key": "issues", "label": "Issues found", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('ebe6109d-0393-5144-bfca-8039d4fe0079'::uuid,'EOC-GIS-03','Incident georeferencing','EOC-GIS-03: where an incident is, and how reliable that is.','c4693fb2-e773-5bae-ad3a-be15c30b6131'::uuid,'{"fields": [{"key": "incident_ref", "label": "Incident or report reference", "type": "text", "required": true}, {"key": "barangay", "label": "Barangay", "type": "text", "required": true}, {"key": "lat", "label": "Latitude", "type": "number", "required": false, "hint": "Decimal degrees, for example 11.0139"}, {"key": "lng", "label": "Longitude", "type": "number", "required": false, "hint": "Decimal degrees, for example 124.6043"}, {"key": "location_status", "label": "Reliability", "type": "select", "required": true, "options": ["Reported", "Preliminary", "Field-verified", "Official"]}]}'::jsonb,'draft',1),
('c748f9ca-4884-5b7c-bd4c-57cfc2386312'::uuid,'EOC-GIS-04','Map product and dissemination register','EOC-GIS-04: maps produced, sources, verification and release.','c4693fb2-e773-5bae-ad3a-be15c30b6131'::uuid,'{"fields": [{"key": "map_title", "label": "Map title", "type": "text", "required": true}, {"key": "prepared_at", "label": "Prepared", "type": "datetime", "required": true}, {"key": "sources", "label": "Data sources", "type": "textarea", "required": true}, {"key": "verification", "label": "Verification status shown on the map", "type": "select", "required": true, "options": ["Reported", "Preliminary", "Field-verified", "Official"]}, {"key": "audience", "label": "Released to", "type": "multiselect", "required": true, "options": ["EOC", "Executive", "Partners", "Public"]}, {"key": "release_approved", "label": "Release approved by the EOC Manager or authorized information officer", "type": "checkbox", "required": true}]}'::jsonb,'draft',1),
('e2242936-9e5c-5da2-8259-255c7dfe5e30'::uuid,'F3-01','Risk information and map request','Annex 3-B. Opens SOP 3-1: who needs what map, for which decision.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'{"fields": [{"key": "requesting_office", "label": "Requesting office", "type": "text", "required": true, "hint": "Office and position, not a personal name"}, {"key": "decision_purpose", "label": "Decision purpose", "type": "select", "required": true, "options": ["Screening", "Public information", "CLUP/CDP planning", "Technical review", "Other"]}, {"key": "hazard", "label": "Hazard", "type": "text", "required": true}, {"key": "geography", "label": "Barangay(s) or area", "type": "textarea", "required": true}, {"key": "scale_format", "label": "Required scale and format", "type": "text", "required": true}, {"key": "required_by", "label": "Required by", "type": "date", "required": true}, {"key": "source_product", "label": "Source product (agency, title, version or date)", "type": "textarea", "required": false}, {"key": "limitations", "label": "Known limitations", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('11eec969-3c03-52f7-9c17-12788df4d950'::uuid,'F3-02','Dataset metadata and quality checklist','Annex 3-C. A dataset is not released until this is complete.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'{"fields": [{"key": "dataset_id", "label": "Dataset ID", "type": "text", "required": true}, {"key": "source_agency", "label": "Source agency and original product", "type": "text", "required": true}, {"key": "source_date", "label": "Source date", "type": "date", "required": true}, {"key": "scale", "label": "Scale or resolution", "type": "text", "required": true}, {"key": "crs", "label": "Coordinate reference system", "type": "text", "required": true, "hint": "For example EPSG:4326"}, {"key": "method", "label": "Method, scenario, baseline and time horizon", "type": "textarea", "required": false}, {"key": "geometry_ok", "label": "Geometry, attributes and legend checked", "type": "checkbox", "required": true}, {"key": "limitations", "label": "Limitations and prohibited uses", "type": "textarea", "required": true}, {"key": "access_class", "label": "Access class", "type": "select", "required": true, "options": ["Public", "Internal", "Confidential", "Personal or sensitive"]}, {"key": "approved_use", "label": "Approved use", "type": "select", "required": true, "options": ["Internal screening", "Public information", "CLUP/CDP planning layer", "Regulatory use"]}]}'::jsonb,'draft',1),
('09cf64c9-3ab9-5c90-ad99-1469dff75a4a'::uuid,'F3-03','CDRA hazard-impact scoping matrix','Annex 3-D. One entry per hazard-sector pathway.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'{"fields": [{"key": "hazard", "label": "Hazard or climate stressor", "type": "text", "required": true}, {"key": "source_scenario", "label": "Source, scenario and horizon", "type": "text", "required": true}, {"key": "sectors", "label": "Affected sectors", "type": "multiselect", "required": true, "options": ["Population", "Urban use areas", "Natural resource production", "Critical point facilities", "Lifelines", "Ecosystems"]}, {"key": "impact_chain", "label": "Impact chain and area", "type": "textarea", "required": true}, {"key": "data_gap", "label": "Data gap or uncertainty", "type": "textarea", "required": false}, {"key": "validation_owner", "label": "Validation owner (office)", "type": "text", "required": true}]}'::jsonb,'draft',1),
